//SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

library MarketNeutralLib {

    struct EtherMarketNeutralInput {
        string marketLong;
        string marketShort;
        uint256 totalEthAmount;
        uint256 sizeDeltaUsdLong;
        uint256 sizeDeltaUsdShort;
        uint256 executionFee;
        uint256 slippageBps;
    }

    struct UsdcMarketNeutralInput {
        string marketLong;
        string marketShort;
        uint256 totalUsdcAmount;
        uint256 sizeDeltaUsdLong;
        uint256 sizeDeltaUsdShort;
        uint256 executionFee;
        uint256 slippageBps;
    }

    struct EtherOneSideTradeInput {
        uint256 ethAmount;
        uint256 sizeDeltaUsd;
        uint256 acceptablePrice;
        uint256 executionFee;
        uint256 value;
        string market;
        bool isLong;
        address receiver;
    }

    struct UsdcOneSideTradeInput { // check
        uint256 usdcAmount;
        uint256 sizeDeltaUsd;
        uint256 acceptablePrice;
        uint256 executionFee;
        uint256 value;
        string market;
        bool isLong;
        address receiver;
    }

    struct CloseMarketNeutralInput {
        uint256 positionId;
        uint256 executionFee;
        uint256 slippageBps;
    }

    struct CloseSideMarketNeutralInput {
        uint256 positionId;
        uint256 executionFee;
        uint256 slippageBps;
        uint256 value;
        bool isLongSide;
    }

    struct RawExecutionData {
        uint256 positionId;
        address receiver;
        address outputToken;
        uint256 outputAmount;
        int256 pnl;
        uint256 executionPrice;
        uint256 collateralTokenPrice;
        bool isLongSide;
        bool processed;
        uint256 timestamp;
    }

    struct PendingOrder {
        address receiver;
        address proxy;
        uint256 positionId;
        bool isActive;
    }

}

